-- Auchindoun de Draenor (carte 1182) : peuplement du donjon (321 créatures, 29 objets), sorts des créatures de base, scripts de la salle d'Azzakel.
DELETE FROM `creature` WHERE `guid` BETWEEN 10530000 AND 10539999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 10530000 AND 10539999;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 25800000 AND 25809999;
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (76466, 77080, 77694, 77696, 77704, 87073, 87074) AND `AIName` = '' AND `ScriptName` = '';
UPDATE `creature_template` SET `ScriptName` = 'auchindoun_mob_felguard' WHERE `entry` = 79507 AND `ScriptName` = '';
UPDATE `creature_template` SET `ScriptName` = 'auchindoun_mob_cackling_pyromaniac' WHERE `entry` = 79510 AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (76466, 77080, 77694, 77696, 77704, 87073, 87074);
